# -*- coding: utf-8 -*-
"""Traducciones curadas de la interfaz para los idiomas no ingleses.

Se aplican como capa final en ``tools/generate_lang_files.py`` sobre las
traducciones ya presentes en ``lang/<code>.json``. Cubren las claves que usa
``tr()`` y que antes quedaban en inglés (regresion de ``bugs.txt`` Fase 2.3:
"diccionarios incompletos o con texto en ingles dentro de archivos de otros
idiomas").

Cada idioma es un diccionario plano ``seccion.clave`` -> texto. El generador lo
reanida al volcar el JSON. Los marcadores ``{...}``, las etiquetas HTML y los
prefijos con emoji se conservan tal cual.
"""
