# --- Rellenos finales (Fase 2.3) ----------------------------------------- #
# Cadenas largas o sueltas que quedaban en inglés. Se aplican con ``update``
# sobre los diccionarios ya definidos arriba.

_ABOUT = {
    "fr": "<p><b>Package Maker</b> est la suite definitive pour l'ecosysteme Influent OS.</p><p>Concu a pour aider les developpeurs a creer, compiler et distribuer des applications efficacement.</p><br><p>Il utilise le moteur <b>FLARM (Fluthin Armadillo)</b> pour garantir l'integrite et la securite.</p>",
    "de": "<p><b>Package Maker</b> ist die definitive Suite f\u00fcr das \u00d6kosystem von Influent OS.</p><p>Entwickelt, um Entwicklern zu helfen, Anwendungen effizient zu erstellen, zu kompilieren und zu verteilen.</p><br><p>Sie verwendet die <b>FLARM (Fluthin Armadillo)</b>-Engine, um Integrit\u00e4t und Sicherheit zu gew\u00e4hrleisten.</p>",
    "it": "<p><b>Package Maker</b> \u00e8 la suite definitiva per l'ecosistema Influent OS.</p><p>Progettata per aiutare gli sviluppatori a creare, compilare e distribuire applicazioni in modo efficiente.</p><br><p>Utilizza il motore <b>FLARM (Fluthin Armadillo)</b> per garantire integrit\u00e0 e sicurezza.</p>",
    "pt": "<p><b>Package Maker</b> \u00e9 a su\u00edte definitiva para o ecossistema Influent OS.</p><p>Projetada para ajudar desenvolvedores a criar, compilar e distribuir aplica\u00e7\u00f5es com efici\u00eancia.</p><br><p>Utiliza o motor <b>FLARM (Fluthin Armadillo)</b> para garantir integridade e seguran\u00e7a.</p>",
    "nl": "<p><b>Package Maker</b> is de definitieve suite voor het ecosysteem van Influent OS.</p><p>Ontworpen om ontwikkelaars te helpen applicaties effici\u00ebnt te maken, compileren en distribueren.</p><br><p>Het gebruikt de <b>FLARM (Fluthin Armadillo)</b>-engine om integriteit en veiligheid te waarborgen.</p>",
    "pl": "<p><b>Package Maker</b> to ostateczny zestaw narz\u0119dzi dla ekosystemu Influent OS.</p><p>Zaprojektowany, aby pom\u00f3c programistom efektywnie tworzy\u0107, kompilowa\u0107 i dystrybuowa\u0107 aplikacje.</p><br><p>Wykorzystuje silnik <b>FLARM (Fluthin Armadillo)</b> do zapewnienia integralno\u015bci i bezpiecze\u0144stwa.</p>",
    "tr": "<p><b>Package Maker</b>, Influent OS ekosistemi i\u00e7in nihai pakettir.</p><p>Geli\u015ftiricilerin uygulamalar\u0131 verimli bir \u015fekilde olu\u015fturmas\u0131na, derlemesine ve da\u011f\u0131tmas\u0131na yard\u0131mc\u0131 olmak i\u00e7in tasarlanm\u0131\u015ft\u0131r.</p><br><p>B\u00fct\u00fcnl\u00fck ve g\u00fcvenli\u011fi sa\u011flamak i\u00e7in <b>FLARM (Fluthin Armadillo)</b> motorunu kullan\u0131r.</p>",
    "ru": "<p><b>Package Maker</b> \u2014 \u044d\u0442\u043e \u043e\u043a\u043e\u043d\u0447\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u043d\u0430\u0431\u043e\u0440 \u0434\u043b\u044f \u044d\u043a\u043e\u0441\u0438\u0441\u0442\u0435\u043c\u044b Influent OS.</p><p>\u0421\u043e\u0437\u0434\u0430\u043d, \u0447\u0442\u043e\u0431\u044b \u043f\u043e\u043c\u043e\u0447\u044c \u0440\u0430\u0437\u0440\u0430\u0431\u043e\u0442\u0447\u0438\u043a\u0430\u043c \u044d\u0444\u0444\u0435\u043a\u0442\u0438\u0432\u043d\u043e \u0441\u043e\u0437\u0434\u0430\u0432\u0430\u0442\u044c, \u0441\u0431\u0438\u0440\u0430\u0442\u044c \u0438 \u0440\u0430\u0441\u043f\u0440\u043e\u0441\u0442\u0440\u0430\u043d\u044f\u0442\u044c \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u044f.</p><br><p>\u0418\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442 \u0434\u0432\u0438\u0436\u043e\u043a <b>FLARM (Fluthin Armadillo)</b> \u0434\u043b\u044f \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0435\u043d\u0438\u044f \u0446\u0435\u043b\u043e\u0441\u0442\u043d\u043e\u0441\u0442\u0438 \u0438 \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u0438.</p>",
    "ja": "<p><b>Package Maker</b> \u306f Influent OS \u30a8\u30b3\u30b7\u30b9\u30c6\u30e0\u306e\u305f\u3081\u306e\u6c7a\u5b9a\u7684\u306a\u30b9\u30a4\u30fc\u30c8\u3067\u3059\u3002</p><p>\u958b\u767a\u8005\u304c\u30a2\u30d7\u30ea\u30b1\u30fc\u30b7\u30e7\u30f3\u3092\u52b9\u7387\u7684\u306b\u4f5c\u6210\u3001\u30b3\u30f3\u30d1\u30a4\u30eb\u3001\u914d\u5e03\u3067\u304d\u308b\u3088\u3046\u8a2d\u8a08\u3055\u308c\u3066\u3044\u307e\u3059\u3002</p><br><p>\u5b8c\u5168\u6027\u3068\u30bb\u30ad\u30e5\u30ea\u30c6\u30a3\u3092\u78ba\u4fdd\u3059\u308b\u305f\u3081\u306b <b>FLARM (Fluthin Armadillo)</b> \u30a8\u30f3\u30b8\u30f3\u3092\u4f7f\u7528\u3057\u3066\u3044\u307e\u3059\u3002</p>",
    "ko": "<p><b>Package Maker</b>\ub294 Influent OS \uc5d0\ucf54\uc2dc\uc2a4\ud15c\uc744 \uc704\ud55c \ucd5c\uc885 \uc2a4\uc704\ud2b8\uc785\ub2c8\ub2e4.</p><p>\uac1c\ubc1c\uc790\uac00 \uc571\uc744 \ud6a8\uc728\uc801\uc73c\ub85c \ub9cc\ub4e4\uace0 \ucef4\ud30c\uc77c\ud558\uace0 \ubc30\ud3ec\ud560 \uc218 \uc788\ub3c4\ub85d \uc124\uacc4\ub418\uc5c8\uc2b5\ub2c8\ub2e4.</p><br><p>\ubb34\uacb0\uc131\uacfc \ubcf4\uc548\uc744 \ubcf4\uc7a5\ud558\uae30 \uc704\ud574 <b>FLARM (Fluthin Armadillo)</b> \uc5d4\uc9c4\uc744 \uc0ac\uc6a9\ud569\ub2c8\ub2e4.</p>",
    "zh": "<p><b>Package Maker</b> \u662f Influent OS \u751f\u6001\u7cfb\u7edf\u7684\u7ec8\u6781\u5957\u4ef6\u3002</p><p>\u65e8\u5728\u5e2e\u52a9\u5f00\u53d1\u8005\u9ad8\u6548\u5730\u521b\u5efa\u3001\u7f16\u8bd1\u548c\u53d1\u5e03\u5e94\u7528\u7a0b\u5e8f\u3002</p><br><p>\u5b83\u4f7f\u7528 <b>FLARM (Fluthin Armadillo)</b> \u5f15\u64ce\u6765\u786e\u4fdd\u5b8c\u6574\u6027\u548c\u5b89\u5168\u6027\u3002</p>",
    "ar": "<p><b>Package Maker</b> \u0647\u0648 \u0627\u0644\u062d\u0632\u0645\u0629 \u0627\u0644\u0646\u0647\u0627\u0626\u064a\u0629 \u0644\u0646\u0637\u0627\u0645 Influent OS.</p><p>\u0645\u064f\u0635\u0645\u0651\u0645 \u0644\u0645\u0633\u0627\u0639\u062f\u0629 \u0627\u0644\u0645\u0637\u0648\u0651\u0631\u064a\u0646 \u0639\u0644\u0649 \u0625\u0646\u0634\u0627\u0621 \u0627\u0644\u062a\u0637\u0628\u064a\u0642\u0627\u062a \u0648\u062a\u0631\u062c\u0645\u062a\u0647\u0627 \u0648\u062a\u0648\u0632\u064a\u0639\u0647\u0627 \u0628\u0643\u0641\u0627\u0621\u0629.</p><br><p>\u064a\u0633\u062a\u062e\u062f\u0645 \u0645\u062d\u0631\u0643 <b>FLARM (Fluthin Armadillo)</b> \u0644\u0636\u0645\u0627\u0646 \u0627\u0644\u0633\u0644\u0627\u0645\u0629 \u0648\u0627\u0644\u0623\u0645\u0627\u0646.</p>",
}

for _code, _text in _ABOUT.items():
    CURATED.setdefault(_code, {})["about.description"] = _text


